function dragForce(rho, v, Cd, A){ return 0.5*rho*v*v*Cd*A; }
function terminalVelocity(m, g, rho, Cd, A){ if(!(rho*Cd*A>0)) return NaN; return Math.sqrt(2*m*g/(rho*Cd*A)); }
function reynolds(rho, v, L, mu){ if(!mu) return NaN; return rho*v*L/mu; }
var EXPORTS={ dragForce:dragForce, terminalVelocity:terminalVelocity, reynolds:reynolds };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.DragForgePure = EXPORTS; }
